from api.application import app
from fastapi.testclient import TestClient


def openapi_document() -> dict:
    """Read the OpenAPI schema generated by the application.

    Returns
    -------
    dict
        OpenAPI document as a dictionary.
    """
    return TestClient(app).get("/openapi.json").json()


def test_bearer_scheme_is_declared_for_swagger_ui():
    schemes = openapi_document()["components"]["securitySchemes"]

    assert schemes["HTTPBearer"]["type"] == "http"
    assert schemes["HTTPBearer"]["scheme"] == "bearer"


def test_protected_routes_declare_the_bearer_requirement():
    paths = openapi_document()["paths"]

    for path, method in [
        ("/api/professor/students", "get"),
        ("/api/token/verify", "get"),
        ("/api/logout", "post"),
    ]:
        assert {"HTTPBearer": []} in paths[path][method]["security"], path


def test_public_routes_do_not_require_the_bearer_scheme():
    paths = openapi_document()["paths"]

    assert "security" not in paths["/api/login"]["post"]
